// Offline sync queue implementation
const SyncQueue = {
  queue: [],

  add(action) {
    this.queue.push({ ...action, timestamp: Date.now() });
    AsyncStorage.setItem('syncQueue', JSON.stringify(this.queue));
  },

  async flush() {
    if (!NetInfo.isConnected) return;
    const pending = [...this.queue];
    for (const action of pending) {
      try {
        await api.execute(action);
        this.queue = this.queue.filter(a => a.timestamp !== action.timestamp);
      } catch (err) {
        console.log('Sync failed, will retry:', action.type);
      }
    }
    AsyncStorage.setItem('syncQueue', JSON.stringify(this.queue));
  }
};
